(() => {
  'use strict';
  const TARGET = [0,1,2,3,4,5,6,7,8];
  const distances = new Map();
  const byDistance = [[],[],[],[],[]];
  const key = (a) => a.join('');
  const shifted = (board, op, reverse) => {
    const b = board.slice();
    const axis = op < 3 ? 0 : 1;
    const n = op % 3;
    const delta = reverse ? 2 : 1;
    for (let i = 0; i < 3; i++) {
      const from = axis === 0 ? n * 3 + i : i * 3 + n;
      const toI = (i + delta) % 3;
      const to = axis === 0 ? n * 3 + toI : toI * 3 + n;
      b[to] = board[from];
    }
    return b;
  };
  const queue = [TARGET];
  distances.set(key(TARGET), 0);
  for (let at = 0; at < queue.length; at++) {
    const current = queue[at];
    const d = distances.get(key(current));
    byDistance[d].push(current);
    if (d === 4) continue;
    for (let op = 0; op < 6; op++) {
      const previous = shifted(current, op, true);
      const k = key(previous);
      if (!distances.has(k)) {
        distances.set(k, d + 1);
        queue.push(previous);
      }
    }
  }
  const mixed = [[],[],[],[],[]];
  const collect = (depth, board, mask) => {
    if (depth > 0 && distances.get(key(board)) === depth && mask === 3) mixed[depth].push(board);
    if (depth === 4) return;
    for (let op = 0; op < 6; op++) collect(depth + 1, shifted(board, op, true), mask | (op < 3 ? 1 : 2));
  };
  collect(0, TARGET, 0);
  for (let d = 2; d <= 4; d++) {
    const seen = new Set();
    mixed[d] = mixed[d].filter((b) => {
      const k = key(b);
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    });
  }
  const random = (seed) => {
    let x = (seed >>> 0) || 0x6d2b79f5;
    return () => {
      x += 0x6d2b79f5;
      let z = x;
      z = Math.imul(z ^ (z >>> 15), z | 1);
      z ^= z + Math.imul(z ^ (z >>> 7), z | 61);
      return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
    };
  };
  const makeBoards = (seed) => {
    const rnd = random(seed);
    return [2,3,4].map((d) => mixed[d][Math.floor(rnd() * mixed[d].length)].slice());
  };
  const isTarget = (b) => b.every((v, i) => v === i);
  const addEffect = (state, kind) => {
    state.effects.push({kind, ttl: kind === 'solve' ? 30 : 10});
    if (state.effects.length > 32) state.effects.shift();
  };
  const apply = (state, op) => {
    state.board = shifted(state.board, op, false);
    state.moves++;
    state.stageMoves++;
    state.score += 10;
    state.interactions++;
    addEffect(state, 'shift');
    if (isTarget(state.board)) {
      state.solved++;
      state.score += 200;
      state.celebrate = 30;
      addEffect(state, 'solve');
      if (state.solved === 3) state.outcome = 'complete';
    }
  };
  const pointerOp = (p) => {
    if (!p) return -1;
    if (p.x >= 0.79 && p.x <= 1 && p.y >= 0.10 && p.y <= 0.82) {
      const row = Math.floor((p.y - 0.10) / 0.24);
      if (row >= 0 && row < 3) return row;
    }
    if (p.y >= 0.82 && p.y <= 1 && p.x >= 0.06 && p.x <= 0.78) {
      const col = Math.floor((p.x - 0.06) / 0.24);
      if (col >= 0 && col < 3) return 3 + col;
    }
    if (p.x >= 0.06 && p.x <= 0.78 && p.y >= 0.10 && p.y <= 0.82) {
      const row = Math.floor((p.y - 0.10) / 0.24);
      return row >= 0 && row < 3 ? row : -1;
    }
    return -1;
  };
  const create = (seed) => {
    const boards = makeBoards(seed >>> 0);
    return {seed: seed >>> 0, boards, board: boards[0].slice(), stage: 0, solved: 0, moves: 0, stageMoves: 0, cursor: 0, outcome: null, tick: 0, score: 0, interactions: 0, effects: [], celebrate: 0, actionHeld: false, pointerHeld: false};
  };
  const step = (state, input) => {
    state.tick++;
    state.effects = state.effects.filter((e) => --e.ttl > 0);
    const pointer = input && input.pointer ? input.pointer : null;
    const pointerEdge = !!pointer && !state.pointerHeld;
    state.pointerHeld = !!pointer;
    const x = input && Number.isFinite(input.x) ? input.x : 0;
    if (x === 1 && state.lastX !== 1) state.cursor = (state.cursor + 1) % 6;
    if (x === -1 && state.lastX !== -1) state.cursor = (state.cursor + 5) % 6;
    state.lastX = x;
    const action = !!(input && input.action);
    const actionEdge = action && !state.actionHeld;
    state.actionHeld = action;
    if (!state.outcome && state.celebrate === 0) {
      const op = pointerEdge ? pointerOp(pointer) : (actionEdge ? state.cursor : -1);
      if (op >= 0) apply(state, op);
    }
    if (state.celebrate > 0) {
      state.celebrate--;
      if (state.celebrate === 0 && state.solved < 3) {
        state.stage = state.solved;
        state.board = state.boards[state.stage].slice();
        state.stageMoves = 0;
      }
    }
    if (!state.outcome && state.tick >= 2700) state.outcome = 'failure';
    return state;
  };
  const observe = (state) => ({tick: state.tick, score: state.score, progress: Math.floor(state.tick / 27), interactions: state.interactions, entities: 9 + state.effects.length, cursor: state.cursor, moves: state.moves, stage: state.stage, solved: state.solved, outcome: state.outcome});
  const terminal = (state) => (state.outcome === 'complete' && state.tick >= 900) || (state.outcome === 'failure' && state.tick >= 2700);
  globalThis.RibbonShiftCore = {create, step, observe, terminal};
})();

(() => {
  'use strict';
  const canvas = document.querySelector('[data-game-canvas]');
  const goal = document.querySelector('[data-ribbon-goal-progress]');
  const score = document.querySelector('[data-game-score]');
  const best = document.querySelector('[data-ribbon-best]');
  const status = document.querySelector('[data-game-status]');
  const result = document.querySelector('[data-ribbon-result]');
  const detail = document.querySelector('[data-ribbon-detail]');
  let reduceQuery;
  let removeMedia = () => {};
  const syncMotion = () => {
    const reduced = !!reduceQuery.matches;
    document.documentElement.dataset.reducedMotion = String(reduced);
    if (globalThis.RibbonPresentation) globalThis.RibbonPresentation.setReducedMotion(reduced);
  };
  const update = (ctx, snapshot, size) => {
    globalThis.RibbonShiftArt.draw(ctx, snapshot, size);
    const state = snapshot.state;
    const shownBest = Number.isFinite(snapshot.best) ? snapshot.best : 0;
    goal.textContent = `${state.solved}/3`;
    score.textContent = String(state.score);
    best.textContent = String(shownBest);
    status.textContent = state.outcome === 'complete' ? 'All mosaics aligned.' : `Stage ${Math.min(3, state.stage + 1)} · elapsed ${Math.floor(state.tick / 27)}%`;
    const done = globalThis.RibbonShiftCore.terminal(state);
    result.hidden = !done;
    if (done) {
      const complete = state.outcome === 'complete';
      result.querySelector('h2').textContent = complete ? 'MOSAICS RESTORED' : 'TIME UP';
      detail.textContent = `${state.solved}/3 restored · ${state.moves} shifts · current score ${state.score} · device best ${shownBest} local practice`;
    }
  };
  const boot = (metadata) => {
    const kit = globalThis.PlayJoltGameKit.create({core: globalThis.RibbonShiftCore, draw: update, canvas, metadata});
    reduceQuery = matchMedia('(prefers-reduced-motion: reduce)');
    syncMotion();
    const listener = () => syncMotion();
    reduceQuery.addEventListener('change', listener);
    removeMedia = () => reduceQuery.removeEventListener('change', listener);
    addEventListener('pagehide', removeMedia, {once:true});
    return kit;
  };
  fetch('./manifest.json').then((r) => r.json()).then(boot).catch((error) => {
    document.querySelector('[data-game-error]').hidden = false;
    document.querySelector('[data-game-error]').textContent = `Could not start practice: ${error.message}`;
  });
})();

(() => {
  'use strict';
  let reduced = false;
  const palette = ['#ef765e','#77d7bb','#f3c65b','#e99b83','#75a9c8','#c887a6','#c8dc8d','#e5b36b','#a893d5'];
  const particleCount = (state) => reduced ? 0 : Math.min(32, state.effects.length * 4);
  const presentation = {
    setReducedMotion(value) { reduced = !!value; },
    snapshot() { return {reducedMotion: reduced, particles: presentation._particles || 0, activeVoices: 0}; },
    _particles: 0
  };
  globalThis.RibbonPresentation = presentation;
  const rr = (ctx,x,y,w,h,r) => { ctx.beginPath(); ctx.roundRect(x,y,w,h,r); };
  const tile = (ctx, value, x, y, s, selected, solved) => {
    const c = palette[value];
    ctx.fillStyle = '#17252d'; rr(ctx,x,y,s,s,s*.08); ctx.fill();
    ctx.save(); rr(ctx,x+3,y+3,s-6,s-6,s*.07); ctx.clip();
    ctx.fillStyle = c; ctx.globalAlpha = .92; ctx.fillRect(x+3,y+3,s-6,s-6);
    ctx.strokeStyle = '#10202a'; ctx.lineWidth = Math.max(2,s*.045);
    for(let n=-s;n<s*2;n+=s*.26){ctx.beginPath();ctx.moveTo(x+n,y+2);ctx.lineTo(x+n+s*.45,y+s-2);ctx.stroke();}
    ctx.globalAlpha=.3;ctx.strokeStyle='#fff4dc';ctx.lineWidth=s*.08;
    ctx.beginPath();ctx.moveTo(x+s*.18,y+s*.76);ctx.quadraticCurveTo(x+s*.5,y+s*.13,x+s*.84,y+s*.36);ctx.stroke();
    ctx.restore();
    ctx.fillStyle='#11242b';ctx.font=`800 ${Math.max(20,s*.31)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(value+1),x+s/2,y+s/2+1);
    if(selected){ctx.strokeStyle='#fff4d3';ctx.lineWidth=Math.max(2,s*.045);rr(ctx,x+2,y+2,s-4,s-4,s*.07);ctx.stroke();}
    if(solved){ctx.strokeStyle='#8ff0ca';ctx.lineWidth=3;rr(ctx,x+5,y+5,s-10,s-10,s*.08);ctx.stroke();}
  };
  const draw = (ctx, snapshot, size) => {
    const state = snapshot.state, w=size.width, h=size.height;
    presentation._particles = particleCount(state);
    ctx.clearRect(0,0,w,h); ctx.fillStyle='#0c1720';ctx.fillRect(0,0,w,h);
    const unit=Math.min(w,h); const ox=(w-unit)/2, oy=(h-unit)/2;
    const X=(v)=>ox+v*unit, Y=(v)=>oy+v*unit;
    ctx.fillStyle='#132631';rr(ctx,X(.035),Y(.065),unit*.93,unit*.88,unit*.035);ctx.fill();
    ctx.strokeStyle='#31505a';ctx.lineWidth=2;rr(ctx,X(.035),Y(.065),unit*.93,unit*.88,unit*.035);ctx.stroke();
    ctx.fillStyle='#f3c65b';ctx.font=`700 ${Math.max(12,unit*.034)}px system-ui`;ctx.textAlign='left';ctx.fillText(`MOSAIC ${state.stage+1}/3`,X(.07),Y(.075));
    const cell=unit*.24, left=X(.06), top=Y(.10), solved=state.celebrate>0;
    for(let i=0;i<9;i++) tile(ctx,state.board[i],left+(i%3)*cell,top+Math.floor(i/3)*cell,cell,i%3===state.cursor&&state.cursor<3?Math.floor(i/3)===state.cursor:false,solved);
    for(let r=0;r<3;r++){
      const x=X(.80),y=Y(.10+.24*r),s=unit*.15;ctx.fillStyle=state.cursor===r?'#f3c65b':'#ef765e';rr(ctx,x,y,s,s,s*.12);ctx.fill();ctx.fillStyle='#17252d';ctx.font=`900 ${Math.max(23,unit*.075)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('→',x+s/2,y+s/2);
    }
    for(let c=0;c<3;c++){
      const x=X(.06+.24*c),y=Y(.83),s=unit*.15;ctx.fillStyle=state.cursor===c+3?'#f3c65b':'#77d7bb';rr(ctx,x,y,s,s,s*.12);ctx.fill();ctx.fillStyle='#17252d';ctx.font=`900 ${Math.max(23,unit*.075)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('↓',x+s/2,y+s/2);
    }
    if(state.celebrate>0){ctx.fillStyle='rgba(10,25,31,.72)';ctx.fillRect(X(.06),Y(.39),unit*.72,unit*.14);ctx.fillStyle='#fff2d7';ctx.font=`900 ${Math.max(18,unit*.065)}px system-ui`;ctx.textAlign='center';ctx.fillText(state.solved===3?'MOSAIC RESTORED':'WOVEN!',X(.42),Y(.48));}
    if(!reduced && state.effects.length){ctx.fillStyle='#f3c65b';for(let i=0;i<presentation._particles;i++){const a=i*2.4+state.tick*.08;const r=unit*(.18+(i%4)*.025);ctx.globalAlpha=.5;ctx.fillRect(X(.42)+Math.cos(a)*r,Y(.46)+Math.sin(a)*r,3,3);}ctx.globalAlpha=1;}
  };
  globalThis.RibbonShiftArt={draw};
})();

(() => {
  'use strict';
  const TARGET = [0, 1, 2, 3, 4, 5, 6, 7, 8];
  const code = (board) => board.join('');
  const shift = (board, operation, reverse) => {
    const out = board.slice();
    const line = operation % 3;
    const offset = reverse ? 2 : 1;
    if (operation < 3) {
      for (let i = 0; i < 3; i++) out[line * 3 + ((i + offset) % 3)] = board[line * 3 + i];
    } else {
      for (let i = 0; i < 3; i++) out[((i + offset) % 3) * 3 + line] = board[i * 3 + line];
    }
    return out;
  };

  const distances = new Map();
  const layers = [[], [], [], [], []];
  const queue = [TARGET];
  distances.set(code(TARGET), 0);
  for (let cursor = 0; cursor < queue.length; cursor++) {
    const board = queue[cursor];
    const distance = distances.get(code(board));
    layers[distance].push(board);
    if (distance === 4) continue;
    for (let operation = 0; operation < 6; operation++) {
      const prior = shift(board, operation, true);
      const id = code(prior);
      if (!distances.has(id)) {
        distances.set(id, distance + 1);
        queue.push(prior);
      }
    }
  }

  const hasMixedShortestRoute = (board, distance, usedAxes) => {
    if (distance === 0) return usedAxes === 3;
    for (let operation = 0; operation < 6; operation++) {
      const next = shift(board, operation, false);
      if (distances.get(code(next)) === distance - 1 && hasMixedShortestRoute(next, distance - 1, usedAxes | (operation < 3 ? 1 : 2))) return true;
    }
    return false;
  };
  const choices = [[], [], [], [], []];
  for (let depth = 2; depth <= 4; depth++) {
    choices[depth] = layers[depth].filter((board) => hasMixedShortestRoute(board, depth, 0));
  }

  const generator = (seed) => {
    let value = (seed >>> 0) || 0x9e3779b9;
    return () => {
      value = (value + 0x6d2b79f5) >>> 0;
      let z = value;
      z = Math.imul(z ^ (z >>> 15), z | 1);
      z ^= z + Math.imul(z ^ (z >>> 7), z | 61);
      return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
    };
  };
  const boardsFor = (seed) => {
    const next = generator(seed);
    return [2, 3, 4].map((depth) => choices[depth][Math.floor(next() * choices[depth].length)].slice());
  };
  const restored = (board) => board.every((tile, index) => tile === index);
  const effect = (state, kind, ttl) => {
    state.effects.push({ kind, ttl });
    if (state.effects.length > 32) state.effects.shift();
  };
  const move = (state, operation) => {
    state.board = shift(state.board, operation, false);
    state.moves += 1;
    state.stageMoves += 1;
    state.score += 10;
    state.interactions += 1;
    effect(state, 'shift', 10);
    if (restored(state.board)) {
      state.solved += 1;
      state.score += 200;
      state.celebrate = 30;
      effect(state, 'restore', 30);
      if (state.solved === 3) state.outcome = 'complete';
    }
  };
  const touchOperation = (pointer) => {
    if (!pointer || !Number.isFinite(pointer.x) || !Number.isFinite(pointer.y)) return -1;
    const x = pointer.x;
    const y = pointer.y;
    if (x >= 0.79 && x <= 1 && y >= 0.10 && y < 0.82) {
      const row = Math.floor((y - 0.10) / 0.24);
      return row >= 0 && row < 3 ? row : -1;
    }
    if (x >= 0.06 && x < 0.78 && y >= 0.82 && y <= 1) {
      const column = Math.floor((x - 0.06) / 0.24);
      return column >= 0 && column < 3 ? column + 3 : -1;
    }
    if (x >= 0.06 && x < 0.78 && y >= 0.10 && y < 0.82) {
      const row = Math.floor((y - 0.10) / 0.24);
      return row >= 0 && row < 3 ? row : -1;
    }
    return -1;
  };
  const create = (seed) => {
    const boards = boardsFor(seed >>> 0);
    return {
      seed: seed >>> 0,
      boards,
      board: boards[0].slice(),
      stage: 0,
      solved: 0,
      moves: 0,
      stageMoves: 0,
      cursor: 0,
      outcome: null,
      tick: 0,
      score: 0,
      interactions: 0,
      effects: [],
      celebrate: 0,
      actionHeld: false,
      pointerHeld: false,
      lastX: 0
    };
  };
  const step = (state, input) => {
    const controls = input || {};
    state.tick += 1;
    state.effects = state.effects.filter((item) => {
      item.ttl -= 1;
      return item.ttl > 0;
    });

    const x = Number.isFinite(controls.x) ? controls.x : 0;
    if (x === 1 && state.lastX !== 1) state.cursor = (state.cursor + 1) % 6;
    if (x === -1 && state.lastX !== -1) state.cursor = (state.cursor + 5) % 6;
    state.lastX = x;

    const pointer = controls.pointer || null;
    const pointerEdge = !!pointer && !state.pointerHeld;
    state.pointerHeld = !!pointer;
    const action = !!controls.action;
    const actionEdge = action && !state.actionHeld;
    state.actionHeld = action;

    if (!state.outcome && state.celebrate === 0) {
      const operation = pointerEdge ? touchOperation(pointer) : (actionEdge ? state.cursor : -1);
      if (operation >= 0) move(state, operation);
    }
    if (state.celebrate > 0) {
      state.celebrate -= 1;
      if (state.celebrate === 0 && state.solved < 3) {
        state.stage = state.solved;
        state.board = state.boards[state.stage].slice();
        state.stageMoves = 0;
      }
    }
    if (!state.outcome && state.tick >= 2700) state.outcome = 'failure';
    return state;
  };
  const observe = (state) => ({
    tick: state.tick,
    score: state.score,
    progress: Math.floor(state.tick / 27),
    interactions: state.interactions,
    entities: 9 + state.effects.length,
    board: state.board.slice(),
    stage: state.stage,
    solved: state.solved,
    moves: state.moves,
    stageMoves: state.stageMoves,
    cursor: state.cursor,
    outcome: state.outcome
  });
  const terminal = (state) => (state.outcome === 'complete' && state.tick >= 900) || (state.outcome === 'failure' && state.tick >= 2700);
  globalThis.RibbonShiftCore = { create, step, observe, terminal };
})();

(() => {
  'use strict';
  const canvas = document.querySelector('[data-game-canvas]');
  const goal = document.querySelector('[data-ribbon-goal-progress]');
  const score = document.querySelector('[data-game-score]');
  const best = document.querySelector('[data-ribbon-best]');
  const status = document.querySelector('[data-game-status]');
  const result = document.querySelector('[data-ribbon-result]');
  const detail = document.querySelector('[data-ribbon-detail]');
  let mediaQuery = null;
  let mediaListener = null;

  const setMotion = () => {
    const reduced = !!(mediaQuery && mediaQuery.matches);
    document.documentElement.dataset.reducedMotion = String(reduced);
    if (globalThis.RibbonPresentation) globalThis.RibbonPresentation.setReducedMotion(reduced);
  };
  const draw = (ctx, snapshot, size) => {
    globalThis.RibbonShiftArt.draw(ctx, snapshot, size);
    const state = snapshot.state;
    const localBest = Number.isFinite(snapshot.best) ? snapshot.best : 0;
    goal.textContent = `${state.solved}/3`;
    score.textContent = String(state.score);
    best.textContent = String(localBest);
    status.textContent = state.outcome === 'complete'
      ? 'Every ribbon is restored. Celebration continues.'
      : `Mosaic ${Math.min(3, state.stage + 1)} of 3 · elapsed ${Math.floor(state.tick / 27)}%`;
    const finished = globalThis.RibbonShiftCore.terminal(state);
    result.hidden = !finished;
    if (finished) {
      const complete = state.outcome === 'complete';
      result.querySelector('h2').textContent = complete ? 'MOSAICS RESTORED' : 'TIME UP';
      result.querySelector('[data-ribbon-result-count]').textContent = `${state.solved}/3`;
      detail.textContent = `${state.solved}/3 restored · ${state.moves} shifts used · current score ${state.score} · device best ${localBest} local practice`;
    }
  };
  const boot = (metadata) => {
    globalThis.PlayJoltGameKit.create({ core: globalThis.RibbonShiftCore, draw, canvas, metadata });
    mediaQuery = globalThis.matchMedia('(prefers-reduced-motion: reduce)');
    mediaListener = setMotion;
    mediaQuery.addEventListener('change', mediaListener);
    setMotion();
    globalThis.addEventListener('pagehide', () => {
      if (mediaQuery && mediaListener) mediaQuery.removeEventListener('change', mediaListener);
    }, { once: true });
  };
  fetch('./manifest.json')
    .then((response) => {
      if (!response.ok) throw new Error('practice manifest unavailable');
      return response.json();
    })
    .then(boot)
    .catch((error) => {
      const errorNode = document.querySelector('[data-game-error]');
      errorNode.hidden = false;
      errorNode.textContent = `Could not start practice: ${error.message}`;
    });
})();

(() => {
  'use strict';
  let reducedMotion = false;
  const colors = ['#ef765e', '#77d7bb', '#f3c65b', '#e99b83', '#75a9c8', '#c887a6', '#c8dc8d', '#e5b36b', '#a893d5'];
  const presentation = {
    particles: 0,
    setReducedMotion(value) { reducedMotion = !!value; },
    snapshot() { return { reducedMotion, particles: presentation.particles, activeVoices: 0 }; }
  };
  globalThis.RibbonPresentation = presentation;
  const rounded = (ctx, x, y, width, height, radius) => {
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x, y, width, height, radius);
    else ctx.rect(x, y, width, height);
  };
  const tile = (ctx, value, x, y, size, selected, checked) => {
    rounded(ctx, x, y, size, size, size * 0.08);
    ctx.fillStyle = '#17252d';
    ctx.fill();
    ctx.save();
    rounded(ctx, x + 3, y + 3, size - 6, size - 6, size * 0.07);
    ctx.clip();
    ctx.fillStyle = colors[value];
    ctx.fillRect(x + 3, y + 3, size - 6, size - 6);
    ctx.strokeStyle = 'rgba(15,31,39,.65)';
    ctx.lineWidth = Math.max(2, size * 0.042);
    for (let stripe = -size; stripe < size * 2; stripe += size * 0.25) {
      ctx.beginPath();
      ctx.moveTo(x + stripe, y + 2);
      ctx.lineTo(x + stripe + size * 0.45, y + size - 2);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(255,248,224,.38)';
    ctx.lineWidth = size * 0.07;
